-- Phase 36.3: client logins (docs/data-model.md `client_contacts`; docs/architecture.md "Login").
-- Generated by drizzle-kit, then these comments by hand.
-- - client_contacts: a person at one of the firm's contracts (clients), with a work email (lower
--   case, one per firm), switched on or off by an admin, who added them (created_by). Goes with its
--   contract (ON DELETE CASCADE: removing a contract removes its client logins). RLS and the tenant
--   policy as every firm table; grants from TABLE_ACCESS (db:migrate).
-- - magic_links and sessions: a third kind, 'client', with client_contact_id (exactly one subject
--   column set for each kind), gone with the contact.
-- - events.actor_type: 'client' (a client contact logging in or sending a request).
CREATE TABLE "client_contacts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"firm_id" uuid NOT NULL,
	"contract_id" uuid NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"is_on" boolean DEFAULT true NOT NULL,
	"created_by" uuid NOT NULL,
	"last_login_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "client_contacts_firm_id_id_key" UNIQUE("firm_id","id"),
	CONSTRAINT "client_contacts_firm_id_email_key" UNIQUE("firm_id","email"),
	CONSTRAINT "client_contacts_email_lower" CHECK ("client_contacts"."email" = lower("client_contacts"."email") and "client_contacts"."email" ~ '^[^@ ]+@[^@ ]+$'
        and char_length("client_contacts"."email") <= 254),
	CONSTRAINT "client_contacts_name_length" CHECK (char_length("client_contacts"."name") between 1 and 120)
);
